use crate::{colors,config::Config,logo,system};
use std::io::{self, Write};
pub fn render(c:&Config)->Result<(),Box<dyn std::error::Error>> { let os=system::os_release(); let mut rows=Vec::new(); let m=&c.modules; if c.general.show_title { let user=std::env::var("USER").unwrap_or_else(|_|"user".into()); let host=system::read("/etc/hostname"); rows.push(("title".into(),format!("{user}@{host}"))); } fn add(rows:&mut Vec<(String,String)>,enabled:bool,key:&str,value:String){if enabled{rows.push((key.to_string(),value));}} add(&mut rows,m.os,"OS",os.get("PRETTY_NAME").cloned().unwrap_or_else(||"Unknown".into())); add(&mut rows,m.kernel,"Kernel",system::read("/proc/sys/kernel/osrelease")); add(&mut rows,m.hostname,"Hostname",system::read("/etc/hostname")); add(&mut rows,m.username,"Username",std::env::var("USER").unwrap_or_else(|_|"Unknown".into())); add(&mut rows,m.shell,"Shell",std::env::var("SHELL").unwrap_or_else(|_|"Unknown".into())); add(&mut rows,m.wm,"DE/WM",std::env::var("XDG_CURRENT_DESKTOP").or_else(|_|std::env::var("XDG_SESSION_TYPE")).unwrap_or_else(|_|"Unknown".into())); add(&mut rows,m.cpu,"CPU",system::cpu()); add(&mut rows,m.memory,"Memory",system::memory()); add(&mut rows,m.uptime,"Uptime",system::uptime()); let key_width=rows.iter().map(|(k,_)|k.chars().count()).max().unwrap_or(0); let art=if c.logo.enabled {logo::get(&c.logo.kind,&c.logo.path,os.get("ID").map(String::as_str).unwrap_or(""),os.get("ID_LIKE").map(String::as_str).unwrap_or(""))}else{String::new()}; let lines:Vec<_>=art.lines().collect(); let logo_width=lines.iter().map(|line|line.chars().count()).max().unwrap_or(0); let mut out=io::BufWriter::new(io::stdout().lock()); for i in 0..lines.len().max(rows.len()){let left=lines.get(i).copied().unwrap_or(""); let padding=logo_width.saturating_sub(left.chars().count())+2; write!(out,"{left}{:padding$}","",padding=padding)?; if let Some((k,v))=rows.get(i){let key=colors::paint(&format!("{k:width$}",width=key_width),&c.display.key_color,c.general.color); let value=colors::paint(v,&c.display.value_color,c.general.color); writeln!(out,"{key}{}{value}",c.display.separator)?;}else{writeln!(out)?;} } Ok(()) }
